type: spec
domain: TEST
keys: [ID]
input: {SRC: {path: source.csv, key: [ID], types: {V: int}}}
output: {path: result.csv, columns: [ID, G, R, Q, M]}
columns:
  - {name: ID, type: str, label: ID}
  - {name: G, type: str, label: G}
  - {name: R, type: int, label: R}
  - {name: Q, type: int, label: Q, derivation: {aggregate: 'COUNT(SRC.*)'}}
  - {name: M, type: float, label: M, derivation: {aggregate: {expr: 'MEAN(R)', group_by: [G]}}}
rows:
  - id: total
    group_by: [SRC.ID, SRC.G]
    derivations:
      ID: SRC.ID
      G: SRC.G
      R: {aggregate: 'SUM(SRC.V * 2) + MAX(SRC.V)'}

